<?php $row=$data['entry']; ?>
<div class="page-heading"><div><p class="eyebrow">KATALOG</p><h1><?= $e($row['name']) ?></h1><p class="lead">Beschreibung und Tags pflegen, ohne das Original zu verändern.</p></div><a href="<?= $e('/files/detail?'.http_build_query(['space'=>$data['space_id'],'entry'=>$row['id']])) ?>">Zur Datei</a></div>
<section class="panel"><h2>Manuelle Angaben</h2><form method="post" action="/catalog/save"><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space_id']) ?>"><input type="hidden" name="entry" value="<?= $e($row['id']) ?>"><input type="hidden" name="entry_revision" value="<?= $e($row['revision']) ?>"><input type="hidden" name="catalog_revision" value="<?= $e($data['catalog']['revision']) ?>">
<label for="catalog-description">Beschreibung</label><textarea id="catalog-description" name="description" rows="8" maxlength="16384" <?= $data['can_write']?'':'readonly' ?>><?= $e($data['catalog']['description']) ?></textarea><p class="field-note">UTF-8-Text bis 16 KiB. Ausgelesene Metadaten bleiben getrennt; Markup wird als Text behandelt.</p>
<label for="catalog-tags">Tags</label><select id="catalog-tags" name="tags[]" multiple size="8" <?= $data['can_write']?'':'disabled' ?>><?php foreach($data['tags'] as$tag): ?><option value="<?= $e($tag['id']) ?>" <?= in_array($tag['id'],$data['selected_tags'],true)?'selected':'' ?>><?= $e($tag['name']) ?></option><?php endforeach ?></select><p class="field-note">Mehrfachauswahl: bis zu 50 Tags je Datei. Ohne Auswahl werden alle Tags dieser Datei entfernt.</p>
