<?php if($data['can_manage_tags']): ?><section class="panel"><h2>Tags dieses Bereichs verwalten</h2><p>Umbenennen wirkt auf alle Referenzen dieses Tags. Löschen ist nur möglich, wenn der Tag auch im Papierkorb keiner Datei mehr zugeordnet ist.</p>
<?php foreach(['create'=>'Tag anlegen','rename'=>'Tag umbenennen','delete'=>'Unbenutzten Tag löschen']as$operation=>$label): ?><form method="post" action="/catalog/tag"><h3><?= $e($label) ?></h3><input type="hidden" name="csrf" value="<?= $e($data['csrf']) ?>"><input type="hidden" name="space" value="<?= $e($data['space_id']) ?>"><input type="hidden" name="entry" value="<?= $e($row['id']) ?>"><input type="hidden" name="operation" value="<?= $e($operation) ?>">
<?php if($operation!=='create'): ?><label for="tag-selection-<?= $e($operation) ?>">Tag</label><select id="tag-selection-<?= $e($operation) ?>" name="selection" required><option value="">Tag auswählen</option><?php foreach($data['tags'] as$tag): ?><option value="<?= $e($tag['id'].':'.$tag['revision']) ?>"><?= $e($tag['name']) ?></option><?php endforeach ?></select><?php endif ?>
<?php if($operation!=='delete'): ?><label for="tag-name-<?= $e($operation) ?>">Tagname</label><input id="tag-name-<?= $e($operation) ?>" name="name" required maxlength="80"><?php endif ?><label><input type="checkbox" name="confirm" value="1" required> Diese Tagänderung bestätigen.</label><button class="button button-outline" type="submit"><?= $e($label) ?></button></form><?php endforeach ?></section><?php endif ?>
